        diff = X - xi
        if metric == 'l2':
            return np.sqrt((diff ** 2).sum(axis=1))
        elif metric == 'l1':
            return np.abs(diff).sum(axis=1)
        elif metric == 'cosine':
            norms = np.sqrt((X ** 2).sum(axis=1)) * np.sqrt((xi ** 2).sum())
            return 1.0 - (X @ xi) / (norms + 1e-8)

    def knn_vote(dists, nearest_y, k, weighted):
        if weighted:
            w = 1.0 / (dists + 1e-8)
            score = (nearest_y * w).sum() / w.sum()
        else:
            score = nearest_y.mean()
        return int(np.round(score))

    best_acc = 0.0
    best_params = (5, 'l2', False)

    for metric in ['l2', 'l1', 'cosine']:
        for weighted in [False, True]:
            for k in [1, 3, 5, 7, 9, 11, 15, 21]:
                correct = 0
                for i in range(len(X_train_s)):
                    X_loo = np.delete(X_train_s, i, axis=0)
                    y_loo = np.delete(y_train, i)
                    d = compute_dists(X_loo, X_train_s[i], metric)
                    nearest = np.argsort(d)[:k]
                    pred = knn_vote(d[nearest], y_loo[nearest], k, weighted)
                    if pred == y_train[i]:
                        correct += 1
                acc = correct / len(X_train_s)
                if acc > best_acc:
                    best_acc = acc
                    best_params = (k, metric, weighted)

    k, metric, weighted = best_params

    preds = []
    for i in range(len(X_test_s)):
        d = compute_dists(X_train_s, X_test_s[i], metric)
        nearest = np.argsort(d)[:k]
        pred = knn_vote(d[nearest], y_train[nearest], k, weighted)
        preds.append(pred)

    predictions = pd.DataFrame({"prediction": preds})
    predictions.to_csv(output_csv, index=False)
