import pandas as pd
import numpy as np


TARGET_COLUMN = 'target'


class DecisionTree:
    def __init__(self, max_depth=5, min_samples=2, max_features=None, rng=None):
        self.max_depth = max_depth
        self.min_samples = min_samples
        self.max_features = max_features
        self.rng = rng or np.random.RandomState(42)
        self.tree = None

    def _gini(self, y):
        if len(y) == 0:
            return 0.0
        p = y.mean()
        return 2 * p * (1 - p)

    def _best_split(self, X, y):
        n, d = X.shape
        if self.max_features:
            features = self.rng.choice(d, min(self.max_features, d), replace=False)
        else:
            features = range(d)

        best_gini = float('inf')
        best_feat = None
        best_thresh = None

        for feat in features:
            vals = np.sort(np.unique(X[:, feat]))
            for j in range(len(vals) - 1):
                thresh = (vals[j] + vals[j+1]) / 2
                left = y[X[:, feat] <= thresh]
                right = y[X[:, feat] > thresh]
                if len(left) < 1 or len(right) < 1:
                    continue
                gini = (len(left) * self._gini(left) + len(right) * self._gini(right)) / n
                if gini < best_gini:
                    best_gini = gini
                    best_feat = feat
                    best_thresh = thresh

        return best_feat, best_thresh

    def _build(self, X, y, depth):
        if depth >= self.max_depth or len(y) < self.min_samples or len(np.unique(y)) == 1:
            return {'leaf': True, 'pred': int(np.round(y.mean()))}

        feat, thresh = self._best_split(X, y)
        if feat is None:
            return {'leaf': True, 'pred': int(np.round(y.mean()))}

        left_mask = X[:, feat] <= thresh
        right_mask = ~left_mask

        if left_mask.sum() == 0 or right_mask.sum() == 0:
            return {'leaf': True, 'pred': int(np.round(y.mean()))}

        return {
            'leaf': False,
            'feat': feat,
            'thresh': thresh,
            'left': self._build(X[left_mask], y[left_mask], depth + 1),
            'right': self._build(X[right_mask], y[right_mask], depth + 1),
        }

    def fit(self, X, y):
        self.tree = self._build(X, y.astype(float), 0)

    def _predict_one(self, x, node):
        if node['leaf']:
            return node['pred']
        if x[node['feat']] <= node['thresh']:
            return self._predict_one(x, node['left'])
        return self._predict_one(x, node['right'])

    def predict(self, X):
        return np.array([self._predict_one(x, self.tree) for x in X])


def predict(train_csv: str, test_csv: str, output_csv: str) -> None:
    """Random forest classifier."""
    train = pd.read_csv(train_csv)
    test = pd.read_csv(test_csv)

    feature_cols = [c for c in train.columns if c != TARGET_COLUMN]
    X_train = train[feature_cols].values
    y_train = train[TARGET_COLUMN].values.astype(int)
    X_test = test[feature_cols].values
    n, d = X_train.shape

    n_trees = 200
    max_features = int(np.sqrt(d))
    rng = np.random.RandomState(42)

    all_preds = np.zeros((len(X_test), n_trees))
    for t in range(n_trees):
        idx = rng.choice(n, n, replace=True)
        tree = DecisionTree(max_depth=5, min_samples=2, max_features=max_features, rng=np.random.RandomState(rng.randint(1e9)))
        tree.fit(X_train[idx], y_train[idx])
        all_preds[:, t] = tree.predict(X_test)

    preds = (all_preds.mean(axis=1) >= 0.5).astype(int)
    predictions = pd.DataFrame({"prediction": preds})
    predictions.to_csv(output_csv, index=False)
